function [icRefA, icRefB, icRefC] = ctrl_gru(vA,vB,vC,iLA,iLB,iLC,Vdc,VdcRef,Ts)
%CTRL_GRU Small GRU (gated recurrent unit) reference-current generator (2025-style deep-learning baseline).
%   Paste this whole file's contents into a Simulink MATLAB Function
%   block with inputs (vA,vB,vC,iLA,iLB,iLC,Vdc,VdcRef,Ts) and outputs
