persistent buf dcInt initialized
persistent Wr Ur br Wz Uz bz Wn Un bn Wo bo
N = 32; H = 8;
if isempty(initialized)
    buf = zeros(1,N); dcInt = 0;
    Wr=[-1.1067319 -0.1915964 0.27127441 0.17057467 0.07283595 0.016259297 0.10517604 -0.026320975]; Ur=[0.81127408 0.18429747 0.079116408 -0.13725732 -0.17408826 -0.51163146 -0.47148728 -0.27367415;-0.10530648 -0.16565347 -0.26034056 0.13536158 0.50832642 0.1771813 0.31607954 -0.053170897;-0.23863905 0.34502227 -0.17972636 -0.092897314 -0.5665213 0.026806949 -0.31619046 -0.44746892;-0.4152209 -0.0010910008 0.092909112 -0.34517412 0.44730984 -0.37147748 -0.0018923359 0.21482033;0.67878444 0.039737309 0.26242516 -0.30360144 -0.48284298 -0.354321 -0.37667828 0.59607027;-0.048450091 -0.023207075 0.15777941 -0.01980183 -0.22768516 -0.60906387 -0.41517191 0.99392909;0.35059153 -0.76888728 0.21590009 -0.24181485 -0.0096681827 -0.47405106 -0.024218127 0.54641766;-0.37485068 0.11472133 0.22218131 0.6232571 -0.25769726 0.63934226 -0.28529979 -0.35236845]; br=[-0.30705766 -0.01165508 -0.18080741 0.014897947 0.22907788 0.23234239 0.11704508 -0.19215732];
    Wz=[-0.050357444 -0.20737535 0.70867356 -0.51658756 -0.35335446 0.31340478 0.046904619 0.45222087]; Uz=[-0.84042392 -0.09369798 -0.37940767 0.5728763 -0.51473268 0.13645126 0.6272888 -0.78678448;0.74768973 -0.47419708 0.21339645 -0.40698113 0.17865737 0.49534348 -0.61577635 0.097322727;0.13735744 -0.36618145 0.30298096 -0.28091862 0.33367669 0.38879997 0.19948411 0.51663817;-0.7073736 0.064124185 0.97847472 0.37756762 0.41970113 -0.13516301 0.10612744 -0.29246975;-0.91703463 -0.072532639 0.18633323 0.39499452 -0.64470223 -0.41078585 0.23835232 -0.37637659;-1.0306371 0.62572072 0.056642381 0.8483116 -1.1343824 -0.4769201 1.3597704 -0.63759032;-0.63807173 0.40725023 -0.60463116 0.82003379 -0.48801647 -0.41084373 0.68974434 -0.84996686;0.61118793 -0.20207966 -0.053066251 -0.97344963 0.77514382 0.40874727 -0.57749149 0.67383433]; bz=[0.35627936 -0.38484048 0.11526477 -0.87158679 0.2875595 0.27440365 -0.048568228 0.18354043];
    Wn=[-0.47762793 0.039833677 0.25032431 0.5056047 -0.5945176 -0.17367343 -0.85667326 0.31777339]; Un=[0.40434644 -0.15444915 -0.09630821 0.29889364 0.65285862 0.26081241 0.61459966 0.084022862;0.59305812 -0.23789506 0.079407293 -0.9752966 -0.38554246 -0.38409008 0.12540621 -0.18540099;-0.38832596 0.083524895 0.02235452 0.43993502 -0.065651565 -0.46745578 -0.22984402 0.030858571;-0.44169078 0.30086443 -0.042612369 0.361529 -0.060053349 -0.092478931 0.24640501 -0.27013127;-0.5735605 0.17826291 0.22123658 0.24036879 0.36476615 -0.10580648 0.23785499 -0.032735624;0.55179685 -0.13614501 0.21992668 0.43912223 0.34082833 0.39760382 0.27241088 -0.41693515;-0.21720214 -0.26848503 -0.25522184 0.62005998 0.18838453 0.48532177 -0.36777148 -0.067240265;0.2410004 0.31740956 0.10673537 -0.23978525 -0.53546345 -0.12134719 -0.38202904 -0.48160413]; bn=[-0.20001133 -0.016946139 -0.20056331 -0.177834 -0.21722424 -0.2235752 -0.028447251 0.15598637];
